    {
      "name": "Compute, chips & infrastructure",
      "items": [
        {
          "headline": "Nvidia's board unanimously reinstates Jensen Huang as CEO after US government input; shares close 31% higher",
          "sources": [
            { "name": "Nvidia", "url": "https://nvidianews.nvidia.com/news/nvidia-board-reinstates-jensen-huang-as-president-ceo-and-board-director" },
