{
  "headline": "Applied Digital signs a 150 MW, 18-year hyperscaler lease worth about $5.4 billion",
  "sources": [
    { "name": "Applied Digital (via StockTitan)", "url": "https://www.stocktitan.net/news/APLD/applied-digital-secures-new-150-mw-18-year-lease-with-tier-one-eyghorn9ce7n.html" }
  ],
